// Entrada: el Schedule Trigger semanal o el sobre de evento que entrega
// "Despachar Evento" (HT-51) para reporte.creado y reporte.estado_cambiado.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const TIPOS = ['reporte.creado', 'reporte.estado_cambiado'];

const entrada = $input.first().json;
if (!entrada.tipo) {
  return [{ json: { modo: 'semanal', distrito: '', reporte_id: '' } }];
}
if (!TIPOS.includes(entrada.tipo)) {
  // El despachador marca el evento como fallido: es un error de enrutamiento.
  throw new Error(`La ingesta RAG no esta suscrita a ${entrada.tipo}`);
}
const datos = entrada.datos || {};
const reporteId = UUID.test(String(datos.reporte_id || '')) ? String(datos.reporte_id) : '';
const distrito = typeof datos.distrito === 'string' ? datos.distrito.trim() : '';
return [{ json: { modo: 'evento', evento_id: entrada.id, distrito, reporte_id: reporteId } }];

// Redacta el texto de cada ficha a partir de sus metricas. Solo deja pasar
// las fichas cuyo texto cambio (SHA-256 distinto al guardado): una ficha
// igual no vuelve a gastar cuota de embeddings.
const crypto = require('crypto');
const MODELO = 'gemini-embedding-001';
const FRANJAS = {
  manana: 'la mañana (06:00 a 11:59)',
  tarde: 'la tarde (12:00 a 17:59)',
  noche: 'la noche (18:00 a 05:59)',
};
const num = (v) => Number(v || 0);
const dia = (v) => (v ? String(v).slice(0, 10) : null);
const plural = (n, uno, varios) => `${n} ${n === 1 ? uno : varios}`;
const lista = (v) => (Array.isArray(v) ? v : String(v || '').replace(/[{}]/g, '').split(',').filter(Boolean));

function textoDistrito(f, m) {
  const partes = [`${f.distrito_nombre} (Lima), franja de ${FRANJAS[f.franja]}.`];
  if (!m.onsv_hasta) {
    partes.push('No hay datos de siniestros de la ONSV cargados para Lima.');
  } else if (num(m.siniestros) === 0) {
    partes.push(`Entre ${dia(m.onsv_desde)} y ${dia(m.onsv_hasta)} la ONSV no registró siniestros con víctimas en este distrito en esta franja.`);
  } else {
    partes.push(
      `Entre ${dia(m.onsv_desde)} y ${dia(m.onsv_hasta)} la ONSV registró ` +
      `${plural(num(m.siniestros), 'siniestro', 'siniestros')} con víctimas en este distrito en esta franja, ` +
      `con ${plural(num(m.fallecidos), 'fallecido', 'fallecidos')} y ${plural(num(m.lesionados), 'lesionado', 'lesionados')}.`
    );
    const detalle = [
      m.clase_frecuente && `clase más frecuente: ${m.clase_frecuente}`,
      m.causa_frecuente && `causa principal más frecuente: ${m.causa_frecuente}`,
      m.via_frecuente && `tipo de vía más frecuente: ${m.via_frecuente}`,
    ].filter(Boolean);
    if (detalle.length) partes.push(`${detalle.join('; ')}.`.replace(/^./, (c) => c.toUpperCase()));
  }
  const resueltos = num(m.reportes_resueltos_90d);
  partes.push(resueltos === 0
    ? 'En los últimos 90 días no hubo reportes ciudadanos resueltos en UrbanPulse para esta zona y franja.'
    : `En los últimos 90 días ${resueltos === 1 ? 'se resolvió' : 'se resolvieron'} ${plural(resueltos, 'reporte ciudadano', 'reportes ciudadanos')} en UrbanPulse para esta zona y franja` +
      (m.tipo_reporte_frecuente ? `; el tipo más frecuente fue ${m.tipo_reporte_frecuente}.` : '.'));
  partes.push('Fuentes: ONSV (siniestros con víctimas) y reportes ciudadanos resueltos de UrbanPulse.');
  return partes.join(' ');
}

function textoRedVial(f, m) {
  const partes = [
    `Red vial nacional en Lima (carreteras fiscalizadas por SUTRAN), franja de ${FRANJAS[f.franja]}.`,
    'SUTRAN no indica el distrito de cada siniestro, solo la vía y el kilómetro.',
  ];
  const vias = Array.isArray(m.vias) ? m.vias : [];
  if (!vias.length) {
    partes.push('No hay siniestros de SUTRAN cargados para esta franja.');
  } else {
    const detalle = vias.map((v) =>
      `${v.codigo_via} (${plural(num(v.siniestros), 'siniestro', 'siniestros')}, ` +
      `${plural(num(v.fallecidos), 'fallecido', 'fallecidos')}, ${plural(num(v.heridos), 'herido', 'heridos')}` +
      (v.km_frecuente ? `; kilómetro más frecuente: ${v.km_frecuente})` : ')'));
    partes.push(`Entre ${dia(m.sutran_desde)} y ${dia(m.sutran_hasta)} las vías con más siniestros fueron: ${detalle.join('; ')}.`);
  }
  partes.push('Fuente: SUTRAN.');
  return partes.join(' ');
}

const salida = [];
for (const item of $input.all()) {
  const f = item.json;
  const m = typeof f.metricas === 'string' ? JSON.parse(f.metricas) : (f.metricas || {});
  const contenido = f.ambito === 'distrito' ? textoDistrito(f, m) : textoRedVial(f, m);
  const sha256 = crypto.createHash('sha256').update(`${MODELO}\n${contenido}`).digest('hex');
  if (sha256 === f.sha256_actual) continue;
  salida.push({
    json: {
      clave: f.clave,
      ambito: f.ambito,
      distrito: f.distrito || '',
      franja: f.franja,
      fuentes: lista(f.fuentes),
      metricas: m,
      contenido,
      contenido_sha256: sha256,
      modelo_embedding: MODELO,
    },
  });
}
return salida;

// batchEmbedContents acepta hasta 100 textos por llamada.
const TAMANO_LOTE = 100;
const fichas = $input.all().map((i) => i.json);
const lotes = [];
for (let i = 0; i < fichas.length; i += TAMANO_LOTE) {
  const lote = fichas.slice(i, i + TAMANO_LOTE);
  lotes.push({
    json: {
      fichas: lote,
      requests: lote.map((f) => ({
        model: `models/${f.modelo_embedding}`,
        content: { parts: [{ text: f.contenido }] },
        // El lado de consulta (HT-50 T02) debe usar taskType RETRIEVAL_QUERY
        // con el mismo modelo y la misma dimension.
        taskType: 'RETRIEVAL_DOCUMENT',
        outputDimensionality: 768,
      })),
    },
  });
}
return lotes;

// Empareja cada embedding con su ficha y rechaza respuestas incompletas:
// guardar una ficha sin su vector correcto romperia la busqueda.
const DIMENSION = 768;
const lotes = $('Armar lotes de embeddings').all();
const respuestas = $input.all();
if (lotes.length !== respuestas.length) {
  throw new Error(`Se enviaron ${lotes.length} lotes a Gemini y volvieron ${respuestas.length} respuestas`);
}
const salida = [];
respuestas.forEach((respuesta, i) => {
  const fichas = lotes[i].json.fichas;
  const embeddings = respuesta.json.embeddings || [];
  if (embeddings.length !== fichas.length) {
    throw new Error(`Gemini devolvio ${embeddings.length} embeddings para ${fichas.length} fichas`);
  }
  fichas.forEach((ficha, j) => {
    const valores = embeddings[j] && embeddings[j].values;
    if (!Array.isArray(valores) || valores.length !== DIMENSION || !valores.every(Number.isFinite)) {
      throw new Error(`Embedding invalido para ${ficha.clave}`);
    }
    salida.push({
      json: {
        ...ficha,
        embedding: `[${valores.join(',')}]`,
        fuentes_json: JSON.stringify(ficha.fuentes),
        metricas_json: JSON.stringify(ficha.metricas),
      },
    });
  });
});
return salida;
